SELECT COUNT(*)
FROM pay_trade_order
WHERE tenant_id = #{tenantId}
  AND config_revision_id = #{revisionId}
  AND del_flag = '0'

SELECT COUNT(*)
FROM pay_trade_order
WHERE tenant_id = #{tenantId}
  AND terminal_type = #{terminalType}
  AND trade_type LIKE CONCAT(#{tradeTypePrefix}, '%')
  AND del_flag = '0'
